res = [json.loads(l) for l in data_results.strip().split("\n") if l.strip()]
df = pd.DataFrame(res)
fpd = pd.DataFrame([json.loads(l) for l in data_fp.strip().split("\n") if l.strip()])
df["margin"] = df["z"] - df["thr"]
out = []

def wilson_lo(k, n, z=1.96):
    p = k / n
    d = 1 + z * z / n
    c = p + z * z / (2 * n)
    m = z * ((p * (1 - p) / n + z * z / (4 * n * n)) ** 0.5)
    return (c - m) / d

n_img = df["image"].nunique()
out.append("[A] 데이터: %d건, 이미지 %d장, 공격 %d종" % (len(df), n_img, df["attack"].nunique()))

# 1. 성공률과 신뢰구간 (행 단위는 과대평가: 같은 이미지가 11번 반복되므로 이미지 단위도 함께 본다)
ok_all = int(df["ok"].sum())
img_ok = int(df.groupby("image")["ok"].all().sum())
out.append("[1] 성공 %d/%d (행 단위 Wilson 95%% 하한 %.1f%%) | 모든 공격을 통과한 이미지 %d/%d (이미지 단위 하한 %.1f%%)"
           % (ok_all, len(df), 100 * wilson_lo(ok_all, len(df)), img_ok, n_img, 100 * wilson_lo(img_ok, n_img)))

# 2. z와 판정 기준 대비 여유 (z는 이론 상한 sqrt(128)=11.31 근처에서 포화되므로 평균 비교보다 여유가 중요)
out.append("[2] z: 최소 %.2f | 1퍼센타일 %.2f | 중앙값 %.2f | 표준편차 %.3f" % (df.z.min(), df.z.quantile(0.01), df.z.median(), df.z.std()))
out.append("    판정 기준 대비 여유(z-thr): 최소 %.2f | 1퍼센타일 %.2f | 중앙값 %.2f" % (df.margin.min(), df.margin.quantile(0.01), df.margin.median()))

# 3. 공격별 요약
g = df.groupby("attack").agg(성공=("ok", "sum"), n=("ok", "size"), z평균=("z", "mean"), z최소=("z", "min"), 여유최소=("margin", "min"),
                              초평균=("sec", "mean"), 초p95=("sec", lambda s: s.quantile(0.95)), 초최대=("sec", "max")).round(2)
out.append("[3] 공격별 요약\n" + g.to_string())

# 4. none vs jpeg q40: 대응 비교는 맞다. 다만 p값만이 아니라 효과 크기와 신뢰구간을 같이 본다
piv = df.pivot(index="image", columns="attack", values="z")
d = (piv["none"] - piv["jpeg q40"]).values
rng = np.random.default_rng(0)
boot = np.array([rng.choice(d, len(d), replace=True).mean() for _ in range(5000)])
w = stats.wilcoxon(d)
out.append("[4] none - jpeg q40 (대응 n=%d): 평균 차이 %.3f z | 부트스트랩 95%% 구간 [%.3f, %.3f] | Cohen dz %.2f | Wilcoxon p=%.2e | 차이>0인 쌍 %d"
           % (len(d), d.mean(), np.percentile(boot, 2.5), np.percentile(boot, 97.5), d.mean() / d.std(ddof=1), w.pvalue, int((d > 0).sum())))
out.append("    => 통계적으로 유의해도 차이는 z 11 규모에서 %.2f 수준이고, q40의 최소 z는 %.2f(기준 약 6.9)입니다." % (d.mean(), piv["jpeg q40"].min()))

# 5. 공격 간 차이: 같은 이미지를 반복 측정했으므로 Friedman(이미지를 블록으로)이 맞다
fr = stats.friedmanchisquare(*[piv[c].values for c in piv.columns])
means = piv.mean()
out.append("[5] Friedman(이미지 블록, %d블록 x %d공격): chi2=%.1f, p=%.2e | 공격별 평균 z 범위 %.2f~%.2f (차이 %.2f)"
           % (len(piv), piv.shape[1], fr.statistic, fr.pvalue, means.min(), means.max(), means.max() - means.min()))

# 6. 가장 약한 사례
low = df.nsmallest(5, "z")[["image", "attack", "z", "thr", "sync_z", "size"]].round(2)
out.append("[6] z가 가장 낮은 5건\n" + low.to_string(index=False))
out.append("    sync_z와 z의 상관 r=%.2f (이미지/공격 군집 때문에 기술 통계로만 해석)" % stats.pearsonr(df.z, df.sync_z)[0])

# 7. 오탐 시험
chk = fpd[fpd["checked"] == True]
out.append("[7] 오탐 시험: %d건 중 오탐 %d건 | 최대 z %.2f (기준 %.2f~%.2f)" % (len(chk), int(chk["false_positive"].sum()), chk.max_z.max(), chk.thr.min(), chk.thr.max()))

# 8. 속도
out.append("[8] 검출 시간: 총 %.0f CPU분 | 평균 %.1f초 | p95 %.0f초 | 최대 %.0f초" % (df.sec.sum() / 60, df.sec.mean(), df.sec.quantile(0.95), df.sec.max()))

print("\n\n".join(out))
